PROV = {}  # nombre de esquema -> bloqueo (para x-provisional a nivel de propiedad se usa el texto)
def P(spec):
    if isinstance(spec, dict): return spec
    kind, _, rest = spec.partition(':')
    arr = kind.startswith('[')
    if arr: kind = kind.strip('[]')
    if kind == 'e':
        vals, _, desc = rest.partition(':'); s = {'type': 'string', 'enum': vals.split(',')}
    elif kind == 'r':
        name, _, desc = rest.partition(':'); s = ref(name)
    else:
        desc = rest
        s = {'m': ref('MoneyCents'), 'd': ref('Date'), 'dt': ref('DateTime'), 'mo': ref('Month'), 'bp': ref('BasisPoints'), 'mi': ref('Milli'),
             'i': {'type': 'integer'}, 's': {'type': 'string'}, 'b': {'type': 'boolean'}}[kind]
        s = dict(s)
    if arr: s = {'type': 'array', 'items': s}
    else: s = dict(s)
    if desc:
        if 'PROVISIONAL' in desc: s['x-provisional'] = True
        s['description'] = desc
    return s
def O(desc, calc=True, **props):
    p = {}; req = []
    for k, v in props.items():
        opt = k.endswith('_') and not k.endswith('__'); name = k[:-1] if opt else k
        p[name] = P(v)
        if not opt: req.append(name)
    s = {'type': 'object', 'description': desc, 'properties': p}
    if req: s['required'] = req
    if calc: s['x-calculado'] = True
    return s
def A(item, desc): return {'type': 'array', 'items': item if isinstance(item, dict) else P(item), 'description': desc}
def C(spec): return P(spec)  # propiedad calculada en un esquema de entidad

